package com.tdp.telco.service;

import com.tdp.telco.entity.Plan;
import com.tdp.telco.exception.NotFoundException;
import com.tdp.telco.repository.PlanRepository;

import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

/**
 * Exercise 1 - the same cache-aside flow, generated by Spring.
 */
@Service
public class AnnotatedPlanService {

	private final PlanRepository repository;

	public AnnotatedPlanService(PlanRepository repository) {
		this.repository = repository;
	}

	// Spring does GET plans::{id} -> on miss call this method -> SET plans::{id} with the
	// cache's TTL (configured in CacheConfig). Exactly what ManualPlanService does by hand.
	@Cacheable(cacheNames = "plans", key = "#id")
	public Plan getPlan(String id) {
		return repository.findById(id).orElseThrow(() -> new NotFoundException("Plan", id));
	}

}
